import grackle._
import grackle.Predicate.{Const, Eql}
import grackle.Query.Filter
import grackle.QueryCompiler.{Elab, SelectElaborator}
import grackle.Value.StringValue

override val selectElaborator = SelectElaborator {
  case (QueryType, "country", List(Binding("code", StringValue(code)))) =>
    Elab.transformChild(child =>
      Unique(Filter(Eql(CountryType / "code", Const(code)), child)))
}

// AND of two negated less-thans (population >= min AND indepyear >= year)
Filter(
  And(
    Not(Lt(CountryType / "population", Const(min))),
    Not(Lt(CountryType / "indepyear", Const(Option(year))))
  ),
  child)

// membership against a static list
Filter(In(CityType / "language", languages), child)

// list-field contains an element
Filter(Contains(ItemType / "tags", Const(tag)), child)

// null / not-null test over an Option field
Filter(IsNull[Int](CountryType / "indepyear", isNull = !indep), child)

// SQL-style wildcard match (case-insensitive); Like is in grackle.sql
Filter(Like(CityType / "name", namePattern, true), child)

